layer.css:
[data-ryt="footer"] { background-color: rgb(255, 152, 0); font-style: normal; letter-spacing: normal; text-transform: none; color: var(--ryt-text) }
[data-ryt="button"] { color: var(--ryt-bg); background-color: rgb(3, 169, 244); border-radius: 2px; box-shadow: color-mix(in srgb, var(--ryt-text) 14%, transparent) 0px 2px 2px 0px, color-mix(in srgb, var(--ryt-text) 12%, transparent) 0px 3px 1px -2px, color-mix(in srgb, var(--ryt-text) 20%, transparent) 0px 1px 5px 0px; font-family: var(--ryt-font-body); font-weight: 400; font-style: normal; line-height: 2.571; letter-spacing: 0.5px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 16px; padding-bottom: 0px; padding-left: 16px; transition: 0.3s ease-out }
[data-ryt="brand"] { color: #808080; border-radius: 0px; font-family: var(--ryt-font-body); font-size: 31.5px; font-weight: 400; font-style: normal; line-height: 2.032; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: #808080; border-radius: 0px; font-family: var(--ryt-font-body); font-size: 15px; font-weight: 400; font-style: normal; line-height: 4.267; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 15px; padding-bottom: 0px; padding-left: 15px; transition: background-color 0.3s }
[data-ryt="nav"] a:hover { background-color: color-mix(in srgb, var(--ryt-text) 10%, transparent) }
[data-ryt="button"]:hover { box-shadow: color-mix(in srgb, var(--ryt-text) 14%, transparent) 0px 3px 3px, color-mix(in srgb, var(--ryt-text) 12%, transparent) 0px 1px 7px, color-mix(in srgb, var(--ryt-text) 20%, transparent) 0px 3px 1px -1px; background-color: rgb(43, 187, 173) }
